css:
/*
ERPNext Web Page CSS
Your existing LIFE green + white dashboard theme is preserved.
*/

.ref-wrap {
  margin-left: auto;
  margin-right: auto;
}

.navbar { display: none; }
.web-footer { display: none; }

/* ============================================================
   EMPLOYEE / BRANCH / MODE OF PAYMENT DASHBOARD
   LIFE GREEN + WHITE THEME
   No CSS variables are used.
   ============================================================ */

.ref-wrap,
.ref-wrap * {
  box-sizing: border-box;
}

.ref-wrap {
  width: 100%;
  overflow: visible;
  color: #152418;
  font-family: "Inter", "Segoe UI", Arial, system-ui, sans-serif;
  font-size: 12px;
  line-height: 1.45;
  background: #F3FAF4;
  border: 1px solid #DCE9DE;
  border-radius: 14px;
  box-shadow:
    0 1px 2px rgba(15, 61, 30, 0.06),
    0 8px 26px rgba(15, 61, 30, 0.09);
}

/* HEADER */

.ref-header {
  /*display: flex;*/
  /*align-items: center;*/
  /*justify-content: space-between;*/
  /*gap: 22px;*/
  /*min-height: 112px;*/
  /*padding: 20px 24px;*/
  /*color: #FFFFFF;*/
  /*background: #1B5E20;*/
  /*border-radius: 13px 13px 0 0;*/
  /*box-shadow: 0 2px 14px rgba(15, 61, 30, 0.24);*/
  display:none;
}

.ref-header-main {
  flex: 1 1 auto;
  min-width: 0;
}

.ref-header-kicker {
  margin-bottom: 5px;
  color: #BFE3C4;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}

.ref-header .h1 {
  display: block;
  max-width: 1000px;
  color: #FFFFFF !important;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: 0.15px;
  line-height: 1.38;
  overflow-wrap: anywhere;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.22);
}

.ref-title-dot {
  display: inline-block;
  margin: 0 5px;
  color: #81C784;
  font-weight: 900;
}

.ref-header .sub {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin-top: 8px;
  color: #DDF5E1;
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.45;
}

.ref-sub-sep {
  color: rgba(255, 255, 255, 0.42);
}

.ref-header .right {
  flex: 0 0 auto;
  max-width: 310px;
  padding: 8px 13px;
  color: #E8F5E9;
  font-size: 10px;
  font-weight: 600;
  line-height: 1.35;
  text-align: right;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
}

.ref-source-label {
  margin-right: 5px;
  color: #A5D6A7;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

.ref-gold-bar {
  height: 4px;
  background: #43A047;
}

/* NAVIGATION */

.ref-nav {
  display: flex;
  gap: 6px;
  padding: 10px 16px 0;
  overflow-x: auto;
  background: #FFFFFF;
  border-bottom: 1px solid #DCE9DE;
}

.ref-mnav {
  min-height: 38px;
  padding: 0 15px;
  color: #5F6F63;
  font-family: inherit;
  font-size: 11.5px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  background: transparent;
  border: 1px solid transparent;
  border-bottom: 3px solid transparent;
  border-radius: 9px 9px 0 0;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease;
}

.ref-mnav:hover {
  color: #14501F;
  background: #F3FAF4;
}

.ref-mnav.on {
  color: #14501F;
  background: #E8F5E9;
  border-color: #DCE9DE;
  border-bottom-color: #2E7D32;
}

/* CONTENT */

.ref-content {
  padding: 18px 20px 24px;
  background: #F3FAF4;
}

.ref-mode {
  display: none;
}

.ref-mode.on {
  display: block;
}

/* FILTER PANEL */

.ref-fbar {
  margin-bottom: 16px;
  padding: 16px;
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 14px;
  box-shadow:
    0 1px 2px rgba(15, 61, 30, 0.05),
    0 5px 16px rgba(15, 61, 30, 0.07);
}

.ref-fbar-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 13px;
  padding-bottom: 11px;
  border-bottom: 1px dashed #CFE1D2;
}

.ref-filter-title {
  color: #0F3D1E;
  font-size: 13px;
  font-weight: 900;
}

.ref-filter-help {
  margin-top: 2px;
  color: #5F6F63;
  font-size: 10px;
}

.ref-fbar-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 10px;
  width: 100%;
}

.ref-secondary-filters {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid #EEF4EF;
}

.ref-field {
  flex: 1 1 155px;
  min-width: 135px;
}

.ref-primary-filters .ref-field:nth-child(5),
.ref-primary-filters .ref-field:nth-child(6) {
  flex-basis: 190px;
}

.ref-amount-field {
  flex: 1 1 135px;
}

.ref-lbl {
  display: block;
  margin-bottom: 5px;
  color: #35633D;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.75px;
  line-height: 1.2;
  text-transform: uppercase;
}

.ref-input {
  width: 100%;
  min-width: 100px;
  height: 34px;
  padding: 0 10px;
  color: #152418;
  font-family: inherit;
  font-size: 11.5px;
  background: #FFFFFF;
  border: 1.5px solid #CFE1D2;
  border-radius: 8px;
  outline: none;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    background 0.15s ease;
}

.ref-input::placeholder {
  color: #87968B;
}

.ref-input:hover:not(:disabled) {
  border-color: #A5D6A7;
}

.ref-input:focus {
  background: #FFFFFF;
  border-color: #43A047;
  box-shadow: 0 0 0 3px rgba(67, 160, 71, 0.12);
}

.ref-input:disabled {
  color: #637668;
  cursor: not-allowed;
  background: #EEF4EF;
  border-color: #D7E4D9;
}

.ref-input option {
  color: #152418;
  background: #FFFFFF;
}

.ref-input.ref-invalid {
  color: #8F1D1D !important;
  background: #FFF7F6 !important;
  border-color: #EF5350 !important;
  box-shadow: 0 0 0 3px rgba(239, 83, 80, 0.10);
}

.ref-num-error {
  margin-top: 4px;
  color: #C62828;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.3;
}

.ref-date-shortcuts {
  display: flex;
  flex: 2 1 470px;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 6px;
  min-width: 300px;
}

.ref-qbtn {
  height: 34px;
  padding: 0 12px;
  color: #14501F;
  font-family: inherit;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  background: #FFFFFF;
  border: 1.5px solid #A5D6A7;
  border-radius: 999px;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.ref-qbtn:hover {
  color: #0F3D1E;
  background: #E8F5E9;
  border-color: #66BB6A;
  transform: translateY(-1px);
}

.ref-qbtn.on {
  color: #FFFFFF;
  background: #1B5E20;
  border-color: #1B5E20;
  box-shadow: 0 3px 9px rgba(27, 94, 32, 0.24);
}

.ref-action-group {
  display: flex;
  flex: 0 0 auto;
  align-items: flex-end;
  gap: 8px;
  margin-left: auto;
}

.ref-apbtn {
  min-width: 155px;
  height: 34px;
  padding: 0 18px;
  color: #FFFFFF;
  font-family: inherit;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  background: #1B5E20;
  border: 1.5px solid #1B5E20;
  border-radius: 9px;
  box-shadow: 0 3px 10px rgba(27, 94, 32, 0.26);
  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease,
    background 0.15s ease;
}

.ref-apbtn:hover {
  background: #2E7D32;
  box-shadow: 0 5px 14px rgba(27, 94, 32, 0.32);
  transform: translateY(-1px);
}

#ref-reset-filters-btn:hover {
  background: #E8F5E9 !important;
}

#ref-global-excel-btn:hover,
#ref-emp-xlsx:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

/* STATUS */

.ref-status {
  margin-bottom: 10px;
  padding: 9px 13px;
  color: #14501F;
  font-size: 10.5px;
  font-weight: 600;
  background: #E8F5E9;
  border: 1px solid #C8E6C9;
  border-radius: 9px;
}

.ref-err {
  margin-bottom: 10px;
  padding: 10px 14px;
  color: #C62828;
  font-size: 11px;
  font-weight: 700;
  background: #FDECEA;
  border: 1px solid #F2B8B5;
  border-radius: 9px;
}

/* KPI TILES */

.ref-tiles {
  display: grid;
  /* Wider cards prevent large Indian-currency values from being clipped. */
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  align-items: stretch;
  gap: 12px;
  margin-bottom: 18px;
}

.ref-tile {
  position: relative;
  min-width: 0;
  min-height: 92px;
  overflow: hidden;
  padding: 14px 16px;
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 13px;
  box-shadow:
    0 1px 2px rgba(15, 61, 30, 0.05),
    0 4px 13px rgba(15, 61, 30, 0.06);
}

.ref-tile::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 5px;
  content: "";
}

.ref-tile .tl {
  margin-bottom: 7px;
  color: #5F6F63;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.55px;
  line-height: 1.3;
  text-transform: uppercase;
}

.ref-tile .tv {
  display: block;
  width: 100%;
  min-width: 0;
  color: #14501F;
  font-size: clamp(17px, 1.25vw, 21px);
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: -0.35px;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}


/* Exact value plus easy-to-read Indian compact amount, e.g. (1.95 CR). */
.ref-tile .tv.ref-amount-with-compact {
  white-space: normal;
}

.ref-compact-amount {
  display: inline;
  margin-left: 6px;
  color: inherit;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: inherit;
  vertical-align: baseline;
  white-space: nowrap;
}

.t-pn {
  background: #FFFFFF;
  border-color: #D4E7D7;
}

.t-pn::before {
  background: #14501F;
}

.t-pn .tv {
  color: #14501F;
}

.t-pg {
  background: #F2FBF3;
  border-color: #B9DFBE;
}

.t-pg::before {
  background: #43A047;
}

.t-pg .tv {
  color: #2E7D32;
}

.t-pgr {
  background: #E8F5E9;
  border-color: #A5D6A7;
}

.t-pgr::before {
  background: #1B5E20;
}

.t-pgr .tv {
  color: #1B5E20;
}

.t-pr {
  background: #FFF7F6;
  border-color: #F2B8B5;
}

.t-pr::before {
  background: #C62828;
}

.t-pr .tv {
  color: #C62828;
}

.t-po {
  background: #FFF9F0;
  border-color: #FFD39A;
}

.t-po::before {
  background: #E65100;
}

.t-po .tv {
  color: #E65100;
}

/* CARDS */

.ref-two-col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 16px;
}

.ref-card {
  margin-bottom: 16px;
  overflow: hidden;
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 14px;
  box-shadow:
    0 1px 2px rgba(15, 61, 30, 0.05),
    0 5px 15px rgba(15, 61, 30, 0.07);
}

.ref-card-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
  min-height: 42px;
  padding: 10px 14px;
  color: #0F3D1E;
  font-size: 12px;
  font-weight: 900;
  background: #E8F5E9;
  border-bottom: 1px solid #CFE1D2;
}

.ref-card-hdr .badge {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 2px 9px;
  color: #FFFFFF;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
  background: #2E7D32;
  border-radius: 999px;
}

.ref-card-hdr .sub {
  color: #5F6F63;
  font-size: 9.5px;
  font-weight: 600;
  font-style: normal;
}

.ref-card-body {
  padding: 15px;
}

/* TABLES */

.ref-tbl-wrap {
  max-height: 500px;
  overflow: auto;
  background: #FFFFFF;
}

.ref-tbl-wrap table {
  width: 100%;
  border-collapse: collapse;
  color: #152418;
  font-size: 10.5px;
  white-space: nowrap;
}

.ref-tbl-wrap th {
  position: sticky;
  z-index: 2;
  top: 0;
  padding: 9px 10px;
  color: #FFFFFF;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.55px;
  text-align: left;
  text-transform: uppercase;
  background: #1B5E20;
  border-bottom: 2px solid #43A047;
}

.ref-tbl-wrap td {
  padding: 8px 10px;
  color: #152418;
  vertical-align: middle;
  border-bottom: 1px solid #EEF4EF;
}

.ref-wrap .ref-tbl-wrap tbody tr:nth-child(odd) td {
  background: #FFFFFF;
}

.ref-wrap .ref-tbl-wrap tbody tr:nth-child(even) td {
  background: #F7FBF8;
}

.ref-wrap .ref-tbl-wrap tbody tr:hover td {
  background: #E8F5E9 !important;
}

.ref-tbl-wrap tr:last-child td {
  border-bottom: 0;
}

.rnum {
  font-weight: 700;
  text-align: right !important;
  font-variant-numeric: tabular-nums;
}

/* PILLS */

.rpill {
  display: inline-block;
  padding: 3px 9px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.3px;
  white-space: nowrap;
  border-radius: 999px;
}

.rp-r {
  color: #C62828;
  background: #FDECEA;
}

.rp-g {
  color: #14501F;
  background: #E8F5E9;
}

.rp-n {
  color: #14501F;
  background: #E8F5E9;
  border: 1px solid #C8E6C9;
}

.rp-go {
  color: #1B5E20;
  background: #F2FBF3;
  border: 1px solid #B9DFBE;
}

.rp-gy {
  color: #5F6F63;
  background: #EFF2F0;
}

.rp-o {
  color: #E65100;
  background: #FFF3E0;
}

/* RANKS */

.rrank {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 25px;
  height: 25px;
  color: #FFFFFF;
  font-size: 10.5px;
  font-weight: 800;
  border-radius: 50%;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
}

.rrank-1 {
  background: #B8860B;
}

.rrank-2 {
  background: #8C8C8C;
}

.rrank-3 {
  background: #A9763E;
}

.rrank-n {
  background: #2E7D32;
}

/* BAR CHARTS */

.ref-bar-row {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 9px;
}

.ref-bar-row:last-child {
  margin-bottom: 0;
}

.ref-bar-lbl {
  flex: 0 0 155px;
  width: 155px;
  overflow: hidden;
  color: #354C3A;
  font-size: 10.5px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ref-bar-track {
  flex: 1;
  height: 14px;
  overflow: hidden;
  background: #E8F5E9;
  border-radius: 999px;
}

.ref-bar-fill {
  height: 14px;
  border-radius: 999px;
}

.ref-bar-val {
  flex: 0 0 94px;
  width: 94px;
  color: #14501F;
  font-size: 10.5px;
  font-weight: 800;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* DYNAMIC EMPLOYEE CONTROLS */

#ref-emp-ctrl-row {
  padding: 12px 14px 2px;
}

#ref-emp-srch,
#ref-emp-mop-srch {
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}

#ref-emp-srch:focus,
#ref-emp-mop-srch:focus {
  border-color: #43A047 !important;
  box-shadow: 0 0 0 3px rgba(67, 160, 71, 0.12) !important;
}

/* LOADING */

.ref-loading {
  padding: 32px;
  color: #5F6F63;
  font-size: 12px;
  text-align: center;
}

.ref-wrap .ref-tbl-wrap tbody tr td.ref-loading {
  background: #FFFFFF !important;
}

/* SCROLLBARS */

.ref-wrap ::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.ref-wrap ::-webkit-scrollbar-track {
  background: #EEF4EF;
}

.ref-wrap ::-webkit-scrollbar-thumb {
  background: #A5D6A7;
  border-radius: 999px;
}

.ref-wrap ::-webkit-scrollbar-thumb:hover {
  background: #66BB6A;
}

/* RESPONSIVE */

@media (max-width: 1100px) {
  .ref-header {
    align-items: flex-start;
  }

  .ref-header .right {
    max-width: 240px;
  }

  .ref-primary-filters .ref-field {
    flex-basis: 200px;
  }

  .ref-date-shortcuts {
    flex-basis: 100%;
  }
}

@media (max-width: 900px) {
  .ref-two-col {
    grid-template-columns: 1fr;
  }

  .ref-header {
    flex-direction: column;
    min-height: 0;
  }

  .ref-header .right {
    align-self: flex-start;
    max-width: 100%;
    text-align: left;
  }

  .ref-action-group {
    width: 100%;
    margin-left: 0;
  }

  .ref-action-group .ref-apbtn {
    flex: 1;
  }
}

@media (max-width: 720px) {
  .ref-tiles {
    grid-template-columns: 1fr;
  }

  .ref-tile .tv {
    font-size: 20px;
  }
}

@media (max-width: 640px) {
  .ref-header {
    padding: 17px 16px;
  }

  .ref-header .h1 {
    font-size: 16px;
  }

  .ref-title-dot {
    margin: 0 3px;
  }

  .ref-nav {
    padding-right: 10px;
    padding-left: 10px;
  }

  .ref-content {
    padding: 14px 12px 20px;
  }

  .ref-fbar {
    padding: 13px;
  }

  .ref-field,
  .ref-primary-filters .ref-field:nth-child(5),
  .ref-primary-filters .ref-field:nth-child(6),
  .ref-amount-field {
    flex: 1 1 100%;
    min-width: 100%;
  }

  .ref-date-shortcuts {
    flex-basis: 100%;
    min-width: 100%;
  }

  .ref-qbtn {
    flex: 1 1 auto;
  }

  .ref-action-group {
    flex-direction: column;
    align-items: stretch;
  }

  .ref-apbtn,
  #ref-global-excel-btn {
    width: 100% !important;
    margin-left: 0 !important;
  }

  .ref-bar-lbl {
    flex-basis: 105px;
    width: 105px;
  }

  .ref-bar-val {
    flex-basis: 78px;
    width: 78px;
  }
}

javascript:
/*
ERPNext Web Page JavaScript
Converted from the Custom HTML Block version.

Changes:
- Uses the .ref-wrap element as the dashboard root.
- Removes the Custom HTML Block event interception code.
- Waits for both the DOM and Frappe.
- Prevents duplicate initialization.
*/
(function () {
  'use strict';

  void 0;

  var REF_INIT_RETRIES = 0;
  var REF_MAX_INIT_RETRIES = 100;

  function initReferralReportWebPage() {
    var R = document.querySelector('.ref-wrap');

    if (!R) {
      if (REF_INIT_RETRIES < REF_MAX_INIT_RETRIES) {
        REF_INIT_RETRIES += 1;
        setTimeout(initReferralReportWebPage, 100);
      }
      return;
    }

    if (R.__refWebPageInitialized) {
      return;
    }

    if (typeof window.frappe === 'undefined') {
      if (REF_INIT_RETRIES < REF_MAX_INIT_RETRIES) {
        REF_INIT_RETRIES += 1;
        setTimeout(initReferralReportWebPage, 100);
      }
      return;
    }

    R.__refWebPageInitialized = true;

    var $ = function (id) {
      return R.querySelector('#' + id);
    };

  /* ═══════════════════════════════════════════════════════════
     FORMATTERS
  ═══════════════════════════════════════════════════════════ */
  var fmt = function (n) {
    var value = Number(n || 0);
    if (!isFinite(value)) value = 0;
    return '\u20b9' + value.toLocaleString('en-IN', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2
    });
  };


  /* Compact Indian amount used only inside KPI / information cards.
     Examples: 19518187.56 -> 1.95 CR, 707268.18 -> 7.07 L */
  var compactIndianAmount = function (n) {
    var value = Number(n || 0);
    if (!isFinite(value)) value = 0;

    var absValue = Math.abs(value);
    var divisor = 0;
    var suffix = '';

    if (absValue >= 10000000) {
      divisor = 10000000;
      suffix = 'CR';
    } else if (absValue >= 100000) {
      divisor = 100000;
      suffix = 'L';
    } else if (absValue >= 1000) {
      divisor = 1000;
      suffix = 'K';
    } else {
      return '';
    }

    var compact = (value / divisor).toFixed(2)
      .replace(/\.00$/, '')
      .replace(/(\.\d)0$/, '$1');

    return compact + ' ' + suffix;
  };

  var fmtCardAmount = function (n) {
    var exact = fmt(n);
    var compact = compactIndianAmount(n);

    return exact + (compact
      ? '<span class="ref-compact-amount">(' + compact + ')</span>'
      : '');
  };
  var fmtISO = function (d) {
    if (!d) return '';
    var y = d.getFullYear();
    var m = String(d.getMonth() + 1).padStart(2, '0');
    var day = String(d.getDate()).padStart(2, '0');
    return y + '-' + m + '-' + day;
  };

  var fmtDDMMYY = function (s) {
    if (!s) return '';
    var d = new Date(s);
    if (isNaN(d)) return s;
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return String(d.getDate()).padStart(2, '0') + '-'
         + months[d.getMonth()] + '-'
         + String(d.getFullYear()).slice(-2);
  };

  /* CREDIT TYPE BADGE (ref = referrer, incentive = incentive employee) */
  var creditBadge = function (type) {
    var t = (type || '').toLowerCase();
    if (t === 'ref') {
      return '<span class="rpill" style="background:#E3F2FD;color:#1565C0;font-weight:700">Referrer</span>';
    }
    if (t === 'incentive') {
      return '<span class="rpill" style="background:#FFF3E0;color:#E65100;font-weight:700">Incentive</span>';
    }
    return '';
  };

  var fval = function (id) {
    var el = $(id);
    return el ? (el.value || '').trim() : '';
  };

  var today       = new Date();
  var USER_BRANCH = null;
  var RAW_DATA    = [];

  /*
    EMPLOYEE IDENTITY ALIAS MAP
    ---------------------------
    Some invoice rows contain a real Employee ID through the Healthcare
    Practitioner link, while incentive-only rows may contain only the same
    visible employee name because custom_incentive_employee_name does not
    exactly match Employee.employee_name.

    Example:
      Referrer row   -> B Madhavi + HR-EMP-00223
      Incentive row  -> B Madhavi + blank Employee ID

    Without this map they become two dashboard employees. We learn the
    Employee ID from rows where it is available and reuse it for rows with
    the same normalized display name.
  */
  var EMPLOYEE_NAME_ID_MAP = {};

  /* Permission-aware Branch state for Employee Sale Master. */
  var PERMITTED_BRANCHES = [];
  var BRANCH_ACCESS_RESTRICTED = false;
  var HAS_ALL_BRANCH_ACCESS = false;

  /* ═══════════════════════════════════════════════════════════
     NEW REPORT NORMALIZATION
     Report now returns one row per invoice with two employee shares.
  ═══════════════════════════════════════════════════════════ */
  function num(v) {
    var n = Number(v);
    return isFinite(n) ? n : 0;
  }

  function round2(v) {
    return Math.round((num(v) + Number.EPSILON) * 100) / 100;
  }

  function esc(v) {
    return String(v === null || v === undefined ? '' : v)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /*
     EMPLOYEE GROUPING KEY
     ---------------------
     Primary identity = Employee ID.

     Important real-world case:
       B Madhavi + HR-EMP-00223
       B Madhavi + blank Employee ID

     These must still be one employee. Before rendering, the dashboard builds
     EMPLOYEE_NAME_ID_MAP from rows that have both a visible name and a real
     Employee ID. A blank-ID row with the same visible name then inherits the
     known Employee ID for grouping purposes.
  */

  function normalizedEmployeeName(v) {
    return String(v || '')
      .normalize('NFKC')
      .replace(/\u00A0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  function normalizedEmployeeId(v) {
    return String(v || '')
      .normalize('NFKC')
      .replace(/\u00A0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  function rebuildEmployeeNameIdMap(rows) {
    var candidates = {};

    (rows || []).forEach(function (r) {
      var nameKey = normalizedEmployeeName(r && r.sales_person_name);
      var employeeId = normalizedEmployeeId(r && r.employee_id);

      if (!nameKey || !employeeId) return;

      if (!candidates[nameKey]) {
        candidates[nameKey] = {};
      }

      candidates[nameKey][employeeId] = true;
    });

    EMPLOYEE_NAME_ID_MAP = {};

    Object.keys(candidates).forEach(function (nameKey) {
      var ids = Object.keys(candidates[nameKey]);

      /*
        Only create an alias when the visible name resolves unambiguously
        to one Employee ID. If two different Employee IDs genuinely share
        the same display name, keep them separate.
      */
      if (ids.length === 1) {
        EMPLOYEE_NAME_ID_MAP[nameKey] = ids[0];
      }
    });

    void 0;
  }

  function employeeGroupKey(r) {
    r = r || {};

    var employeeId = normalizedEmployeeId(r.employee_id);
    if (employeeId) {
      return 'employee|' + employeeId;
    }

    var nameKey = normalizedEmployeeName(r.sales_person_name);

    /*
      If this row has no Employee ID but another row with the same visible
      name has one, group this row under that real Employee ID.
    */
    if (nameKey && EMPLOYEE_NAME_ID_MAP[nameKey]) {
      return 'employee|' + EMPLOYEE_NAME_ID_MAP[nameKey];
    }

    /*
      Practitioner ID is used only when Employee ID and name-to-ID alias
      are unavailable.
    */
    var practitionerId = normalizedEmployeeId(r.sales_person_id);
    if (practitionerId) {
      return 'practitioner|' + practitionerId;
    }

    return 'name|' + nameKey;
  }

  function cleanEmployeeDisplayName(v) {
    return String(v || '')
      .normalize('NFKC')
      .replace(/\u00A0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function normalizeReportRow(row) {
    row = row || {};

    var oldCreditType = String(row.credit_type || '').toLowerCase();

    var refName = row.referring_employee || row.custom_referring_name ||
      (oldCreditType === 'ref' ? row.sales_person_name : '') || '';

    var incName = row.incentive_employee || row.custom_incentive_employee_name ||
      (oldCreditType === 'incentive' ? row.sales_person_name : '') || '';

    var refEmployeeId = row.referring_employee_id ||
      (oldCreditType === 'ref' ? row.employee_id : '') || '';

    var incEmployeeId = row.incentive_employee_id ||
      (oldCreditType === 'incentive' ? row.employee_id : '') || '';

    var refPractitionerId = row.referring_practitioner_id ||
      row.sales_person_id || row.ref_practitioner || '';

    var paid = num(row.paid_amount);
    var exGst = num(row.paid_amount_without_gst);
    if (!exGst) exGst = num(row.paid_amount_without_tax);

    var gst = num(row.gst_amount);
    if (!gst) gst = num(row.tax_amount);

    if (!exGst && paid) exGst = paid / 1.05;
    if (!gst && paid) gst = paid - exGst;

    var refShare = num(row.referring_employee_share);
    var incShare = num(row.incentive_employee_share);

    /* Backward compatibility for old report output. */
    if (!refShare && !incShare && exGst) {
      if (oldCreditType === 'ref') {
        refShare = exGst;
      } else if (oldCreditType === 'incentive') {
        incShare = exGst;
      } else if (refName && incName) {
        refShare = exGst / 2;
        incShare = exGst - refShare;
      } else if (refName) {
        refShare = exGst;
      } else if (incName) {
        incShare = exGst;
      }
    }

    var employeeCount = num(row.employee_count);

    var refIdNorm = String(refEmployeeId || '')
      .normalize('NFKC')
      .replace(/\u00A0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();

    var incIdNorm = String(incEmployeeId || '')
      .normalize('NFKC')
      .replace(/\u00A0/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();

    /*
      If both fields resolve to the same Employee ID, this is one employee,
      not two different employees.
    */
    if (refIdNorm && incIdNorm && refIdNorm === incIdNorm) {
      employeeCount = 1;
    } else if (!employeeCount) {
      employeeCount = (refName ? 1 : 0) + (incName ? 1 : 0);
    }

    return {
      invoice: row.invoice || '',
      invoice_date: row.invoice_date || row.posting_date || '',
      posting_date: row.invoice_date || row.posting_date || '',
      branch: row.branch || '',
      customer: row.customer || '',
      client_name: row.client_name || row.patient_name || '',
      booking_type: row.booking_type || row.media || '',

      payment_ids: row.payment_ids || '',
      payment_dates: row.payment_dates || '',
      mode_of_payment: row.mode_of_payment || '',

      referring_employee: refName,
      referring_practitioner_id: refPractitionerId,
      referring_employee_id: refEmployeeId,
      incentive_employee: incName,
      incentive_employee_id: incEmployeeId,

      sharing_type: row.sharing_type || '',
      employee_count: employeeCount,

      paid_amount: paid,
      gst_amount: gst,
      tax_amount: gst,
      paid_amount_without_gst: exGst,
      paid_amount_without_tax: exGst,
      referring_employee_share: refShare,
      incentive_employee_share: incShare,
      total_distributed_amount: num(row.total_distributed_amount) || exGst,
      grand_total: num(row.grand_total),
      outstanding_amount: num(row.outstanding_amount)
    };
  }

  function buildEmployeeCreditRows(invoiceRows) {
    var credits = [];

    (invoiceRows || []).forEach(function (r) {
      var totalEx = num(r.total_distributed_amount) || num(r.paid_amount_without_gst);

      function normId(v) {
        return String(v || '')
          .normalize('NFKC')
          .replace(/\u00A0/g, ' ')
          .replace(/\s+/g, ' ')
          .trim()
          .toLowerCase();
      }

      function pushCredit(type, name, employeeId, practitionerId, share) {
        share = num(share);
        if (!name || share <= 0) return;

        var ratio = totalEx > 0 ? share / totalEx : 1;
        if (!isFinite(ratio) || ratio < 0) ratio = 0;
        if (ratio > 1) ratio = 1;

        credits.push({
          invoice: r.invoice,
          invoice_date: r.invoice_date,
          posting_date: r.invoice_date,
          branch: r.branch,
          customer: r.customer,
          client_name: r.client_name,
          booking_type: r.booking_type,
          payment_ids: r.payment_ids,
          payment_dates: r.payment_dates,
          mode_of_payment: r.mode_of_payment,

          credit_type: type,
          sales_person_name: name,
          employee_id: employeeId || '',
          sales_person_id: practitionerId || '',

          paid_amount_without_tax: share,
          paid_amount_without_gst: share,
          tax_amount: num(r.gst_amount) * ratio,
          gst_amount: num(r.gst_amount) * ratio,
          paid_amount: num(r.paid_amount) * ratio,
          grand_total: num(r.grand_total) * ratio,
          outstanding_amount: num(r.outstanding_amount) * ratio
        });
      }

      var refId = normId(r.referring_employee_id);
      var incId = normId(r.incentive_employee_id);

      /*
        Same employee used as both Referring and Incentive:
        create ONE employee-credit row for this invoice.
        This prevents duplicate employee records in Employee Wise summary.
      */
      if (refId && incId && refId === incId) {
        var combinedShare =
          num(r.referring_employee_share) +
          num(r.incentive_employee_share);

        if (!combinedShare) {
          combinedShare = totalEx;
        }

        pushCredit(
          'ref',
          r.referring_employee || r.incentive_employee,
          r.referring_employee_id || r.incentive_employee_id,
          r.referring_practitioner_id,
          combinedShare
        );

        return;
      }

      pushCredit(
        'ref',
        r.referring_employee,
        r.referring_employee_id,
        r.referring_practitioner_id,
        r.referring_employee_share
      );

      pushCredit(
        'incentive',
        r.incentive_employee,
        r.incentive_employee_id,
        '',
        r.incentive_employee_share
      );
    });

    return credits;
  }

  function getEmployeeFilterState() {
    var empText = fval('ref-f-emp').toLowerCase();
    if (empText === 'all employees') empText = '';

    var empEl = $('ref-f-emp');
    var empId = empEl && empEl.dataset
      ? String(empEl.dataset.value || '').toLowerCase()
      : '';

    return { text: empText, id: empId };
  }

  function invoiceMatchesEmployee(r, state) {
    state = state || getEmployeeFilterState();
    if (!state.id && !state.text) return true;

    var ids = [
      r.referring_employee_id,
      r.referring_practitioner_id,
      r.incentive_employee_id
    ].map(function (v) { return String(v || '').toLowerCase(); });

    var names = [
      r.referring_employee,
      r.incentive_employee
    ].map(function (v) { return String(v || '').toLowerCase(); });

    if (state.id) return ids.indexOf(state.id) >= 0;

    return names.concat(ids).some(function (v) {
      return v.indexOf(state.text) >= 0;
    });
  }

  function filterEmployeeCredits(credits) {
    var state = getEmployeeFilterState();
    if (!state.id && !state.text) return credits || [];

    return (credits || []).filter(function (r) {
      var idValues = [r.employee_id, r.sales_person_id]
        .map(function (v) { return String(v || '').toLowerCase(); });
      var name = String(r.sales_person_name || '').toLowerCase();

      if (state.id) return idValues.indexOf(state.id) >= 0;
      return name.indexOf(state.text) >= 0 || idValues.some(function (v) {
        return v.indexOf(state.text) >= 0;
      });
    });
  }


  /* ═══════════════════════════════════════════════════════════
     LIFESCC CYCLE  (6th → 5th next month)
  ═══════════════════════════════════════════════════════════ */
  function lifeSCCCycle(ref) {
    var d = ref || today, y = d.getFullYear(), mo = d.getMonth(), day = d.getDate();
    if (day >= 6) return { start: new Date(y,mo,6),   end: new Date(y,mo+1,5) };
    return            { start: new Date(y,mo-1,6), end: new Date(y,mo,5)   };
  }

  function prevCycle(ref) {
    var current = lifeSCCCycle(ref);
    var d = new Date(current.start);
    d.setDate(d.getDate() - 1);
    return lifeSCCCycle(d);
  }

  function financialYearCycle(ref) {
    var d = ref || today;
    var y = d.getFullYear();
    var mo = d.getMonth();
    if (mo >= 3) {
      return { start: new Date(y, 3, 1), end: new Date(y + 1, 2, 31) };
    }
    return { start: new Date(y - 1, 3, 1), end: new Date(y, 2, 31) };
  }

  /* ═══════════════════════════════════════════════════════════
     INIT DATES
  ═══════════════════════════════════════════════════════════ */
  var cc = lifeSCCCycle(today);
  $('ref-f-from').value = fmtISO(cc.start);
  $('ref-f-to').value   = fmtISO(cc.end);
  if ($('ref-ts')) {
    $('ref-ts').textContent = today.toLocaleString('en-IN',
      { day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit' });
  }

  /* ═══════════════════════════════════════════════════════════
     QUICK DATE BUTTONS
  ═══════════════════════════════════════════════════════════ */
  R.querySelectorAll('.ref-qbtn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      R.querySelectorAll('.ref-qbtn').forEach(function (b) { b.classList.remove('on'); });
      btn.classList.add('on');

      var rng = btn.getAttribute('data-range');
      var f = '', t = '';

      if (rng === 'today') {
        f = fmtISO(today); t = fmtISO(today);
      } else if (rng === 'yesterday') {
        var yd = new Date(today); yd.setDate(yd.getDate() - 1);
        f = fmtISO(yd); t = fmtISO(yd);
      } else if (rng === 'month') {
        var c = lifeSCCCycle(today); f = fmtISO(c.start); t = fmtISO(c.end);
      } else if (rng === 'lastmonth') {
        var p = prevCycle(today); f = fmtISO(p.start); t = fmtISO(p.end);
      } else if (rng === 'financialyear' || rng === 'year') {
        var fy = financialYearCycle(today); f = fmtISO(fy.start); t = fmtISO(fy.end);
      }

      $('ref-f-from').value = f;
      $('ref-f-to').value = t;
    });
  });

  /* ═══════════════════════════════════════════════════════════
     TAB SWITCHING
  ═══════════════════════════════════════════════════════════ */
  R.querySelectorAll('.ref-mnav').forEach(function (tab) {
    tab.addEventListener('click', function () {
      var n = tab.getAttribute('data-tab');
      R.querySelectorAll('.ref-mnav').forEach(function (t) { t.classList.remove('on'); });
      R.querySelectorAll('.ref-mode').forEach(function (p) { p.classList.remove('on'); });
      tab.classList.add('on');
      $('ref-mode-' + n).classList.add('on');
    });
  });

  $('ref-generate-btn').addEventListener('click', function () { fetchAndRender(); });

  /* ═══════════════════════════════════════════════════════════
     STATUS
  ═══════════════════════════════════════════════════════════ */
  function setStatus(msg, isErr) {
    var el = $('ref-status');
    if (!el) return;
    el.innerHTML = msg
      ? '<div class="'+(isErr?'ref-err':'ref-status')+'">'+msg+'</div>' : '';
  }

  /* ═══════════════════════════════════════════════════════════
     AMOUNT FILTER VALIDATION
  ═══════════════════════════════════════════════════════════ */
  var AMOUNT_FILTER_IDS = ['ref-f-paid-from','ref-f-paid-to','ref-f-out-from','ref-f-out-to'];

  function cleanAmountValue(v) {
    v = String(v || '');
    v = v.replace(/[^\d]/g, '');
    v = v.replace(/^0+(?=\d)/, '');
    return v;
  }

  function getAmountVal(id) {
    var v = fval(id);
    if (v === '') return null;
    return Number(v);
  }

  function clearAmountError(id) {
    var el = $(id);
    if (!el) return;
    el.classList.remove('ref-invalid');
    el.title = '';
    var old = el.parentNode.querySelector('.ref-num-error');
    if (old) old.parentNode.removeChild(old);
  }

  function showAmountError(id, msg) {
    var el = $(id);
    if (!el) return;
    el.classList.add('ref-invalid');
    el.title = msg;
    var old = el.parentNode.querySelector('.ref-num-error');
    if (old) old.parentNode.removeChild(old);
    var div = document.createElement('div');
    div.className = 'ref-num-error';
    div.textContent = msg;
    el.parentNode.appendChild(div);
  }

  function validateAmountFilters(showStatus) {
    var ok = true;
    AMOUNT_FILTER_IDS.forEach(function (id) { clearAmountError(id); });

    var paidFrom = getAmountVal('ref-f-paid-from');
    var paidTo   = getAmountVal('ref-f-paid-to');
    var outFrom  = getAmountVal('ref-f-out-from');
    var outTo    = getAmountVal('ref-f-out-to');

    if (paidFrom !== null && paidTo !== null && paidFrom > paidTo) {
      ok = false;
      showAmountError('ref-f-paid-from', 'Paid From cannot be greater than Paid To');
      showAmountError('ref-f-paid-to', 'Paid To cannot be less than Paid From');
    }
    if (outFrom !== null && outTo !== null && outFrom > outTo) {
      ok = false;
      showAmountError('ref-f-out-from', 'Outstanding From cannot be greater than Outstanding To');
      showAmountError('ref-f-out-to', 'Outstanding To cannot be less than Outstanding From');
    }
    if (!ok && showStatus) {
      setStatus('Please correct the highlighted amount filters.', true);
    }
    return ok;
  }

  function setupAmountFilterValidation() {
    AMOUNT_FILTER_IDS.forEach(function (id) {
      var el = $(id);
      if (!el) return;
      el.type = 'text';
      el.setAttribute('inputmode', 'numeric');
      el.setAttribute('pattern', '[0-9]*');
      el.setAttribute('autocomplete', 'off');

      el.addEventListener('keydown', function (e) {
        var allowedKeys = ['Backspace','Delete','Tab','Enter','ArrowLeft','ArrowRight','Home','End'];
        if (allowedKeys.indexOf(e.key) >= 0) return;
        if ((e.ctrlKey || e.metaKey) && ['a','c','v','x','z'].indexOf(e.key.toLowerCase()) >= 0) return;
        if (!/^\d$/.test(e.key)) e.preventDefault();
      });

      el.addEventListener('input', function () {
        var cleaned = cleanAmountValue(el.value);
        if (el.value !== cleaned) el.value = cleaned;
        validateAmountFilters(false);
      });

      el.addEventListener('paste', function (e) {
        e.preventDefault();
        var text = '';
        if (e.clipboardData && e.clipboardData.getData) text = e.clipboardData.getData('text');
        el.value = cleanAmountValue(text);
        validateAmountFilters(false);
      });

      el.addEventListener('blur', function () {
        el.value = cleanAmountValue(el.value);
        validateAmountFilters(false);
      });
    });
  }

  function rankBadge(i) {
    var c = i===0?'rrank-1':i===1?'rrank-2':i===2?'rrank-3':'rrank-n';
    return '<span class="rrank '+c+'">'+(i+1)+'</span>';
  }

  function getEffectiveBranch() { return USER_BRANCH || fval('ref-f-branch'); }

  /* ═══════════════════════════════════════════════════════════
     DROPDOWN-SEARCH WIDGET
  ═══════════════════════════════════════════════════════════ */
  var _allDrops = [];

  function makeDropdownSearch(opts) {
    opts = opts || {};
    var placeholder = opts.placeholder || 'Search...';
    var liveSearch  = !!opts.liveSearch;
    var onSelect    = opts.onSelect || function () {};
    var disabled    = !!opts.disabled;
    var targetEl    = opts.targetEl;

    var wrap = document.createElement('div');
    wrap.style.cssText =
      'position:relative;display:inline-flex;align-items:center;width:100%;box-sizing:border-box;';

    var inp = document.createElement('input');
    inp.type = 'text';
    inp.placeholder = placeholder;
    inp.disabled = disabled;
    inp.autocomplete = 'off';
    if (disabled) inp.value = placeholder || '';

    inp.style.cssText =
      'flex:1;height:34px;padding:0 36px 0 10px;font-size:11.5px;' +
      'font-family:Inter,Segoe UI,Arial,sans-serif;' +
      'border:1.5px solid ' + (disabled ? '#D7E4D9' : '#A5D6A7') + ';' +
      'border-radius:8px;outline:none;background:' + (disabled ? '#EEF4EF' : '#FFFFFF') + ';' +
      'color:#152418;box-sizing:border-box;width:100%;' +
      'box-shadow:0 1px 2px rgba(15,61,30,.04);' +
      'cursor:' + (disabled ? 'not-allowed' : 'text') + ';';

    if (targetEl && targetEl.id) inp.id = targetEl.id;

    var arrow = document.createElement('span');
    arrow.innerHTML = '&#9660;';
    arrow.style.cssText =
      'position:absolute;right:1px;top:1px;height:32px;width:32px;' +
      'border:none;background:transparent;color:#2E7D32;font-size:9px;padding:0;' +
      'border-radius:0 8px 8px 0;display:flex;align-items:center;justify-content:center;' +
      'pointer-events:none;';

    var drop = document.createElement('div');
    drop.style.cssText =
      'position:fixed;z-index:2147483647;background:#FFFFFF;' +
      'border:1.5px solid #43A047;border-radius:10px;' +
      'box-shadow:0 12px 34px rgba(15,61,30,.22);' +
      'max-height:260px;overflow-y:auto;display:none;min-width:220px;';

    document.body.appendChild(drop);
    _allDrops.push(drop);

    wrap.appendChild(inp);
    wrap.appendChild(arrow);

    if (targetEl && targetEl.parentNode) targetEl.parentNode.replaceChild(wrap, targetEl);

    var isOpen = false, loaded = false, loading = false, allItems = [], debTimer = null;

    function posDrop() {
      var r = inp.getBoundingClientRect();
      drop.style.top = (r.bottom + 4) + 'px';
      drop.style.left = r.left + 'px';
      drop.style.width = Math.max(r.width, 220) + 'px';
    }

    function showDrop() {
      if (disabled) return;
      _allDrops.forEach(function (d) { if (d !== drop) d.style.display = 'none'; });
      posDrop();
      drop.style.display = 'block';
      isOpen = true;
    }

    function closeDropdown() { drop.style.display = 'none'; isOpen = false; }

    function renderLoading(text) {
      drop.innerHTML = '<div style="padding:10px 14px;color:#5F6F63;font-size:12px;">'+text+'</div>';
    }

    function renderItems(items) {
      drop.innerHTML = '';
      if (!items || !items.length) {
        drop.innerHTML = '<div style="padding:10px 14px;color:#5F6F63;font-size:12px;">No results</div>';
        return;
      }
      items.forEach(function (item) {
        var row = document.createElement('div');
        row.style.cssText =
          'padding:9px 14px;cursor:pointer;color:#152418;font-size:12px;' +
          'border-bottom:1px solid #EEF4EF;background:#FFFFFF;' +
          'white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';
        row.title = item.label || '';
        row.textContent = item.label || '';
        row.addEventListener('mouseenter', function () { row.style.background = '#E8F5E9'; });
        row.addEventListener('mouseleave', function () { row.style.background = ''; });
        row.addEventListener('mousedown', function (e) {
          e.preventDefault();
          e.stopPropagation();
          var hasDisplayValue = Object.prototype.hasOwnProperty.call(item, 'displayValue');
          inp.value = hasDisplayValue ? (item.displayValue || '') : (item.value || '');
          inp.dataset.value = item.value || '';
          closeDropdown();
          onSelect(item);
        });
        drop.appendChild(row);
      });
    }

    function filterLocalItems() {
      var term = (inp.value || '').trim().toLowerCase();
      if (!term) { renderItems(allItems); return; }
      renderItems(allItems.filter(function (it) {
        return String(it.label || '').toLowerCase().indexOf(term) >= 0 ||
               String(it.value || '').toLowerCase().indexOf(term) >= 0;
      }));
    }

    function loadItems(term) {
      showDrop();
      if (loading) return;
      loading = true;
      renderLoading(liveSearch ? 'Searching...' : 'Loading...');
      if (liveSearch) {
        opts.supplier(term || '', function (items) {
          allItems = items || []; loaded = true; loading = false;
          showDrop(); renderItems(allItems);
        });
      } else {
        opts.supplier(function (items) {
          allItems = items || []; loaded = true; loading = false;
          showDrop(); filterLocalItems();
        });
      }
    }

    function openDropdown() {
      if (disabled) return;
      showDrop();
      if (liveSearch) {
        clearTimeout(debTimer);
        debTimer = setTimeout(function () { loadItems((inp.value || '').trim()); }, 120);
        return;
      }
      if (!loaded) loadItems(''); else filterLocalItems();
    }

    inp.addEventListener('mousedown', function (e) {
      e.stopPropagation();
      setTimeout(function () { inp.focus(); openDropdown(); }, 0);
    });

    inp.addEventListener('focus', function () { openDropdown(); });

    inp.addEventListener('input', function () {
      if (disabled) return;
      inp.dataset.value = '';
      showDrop();
      if (liveSearch) {
        clearTimeout(debTimer);
        debTimer = setTimeout(function () { loadItems((inp.value || '').trim()); }, 220);
      } else {
        if (!loaded) loadItems(''); else filterLocalItems();
      }
    });

    inp.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') closeDropdown();
    });

    document.addEventListener('mousedown', function (e) {
      if (e.target !== inp && !wrap.contains(e.target) && !drop.contains(e.target)) closeDropdown();
    }, true);

    window.addEventListener('scroll', function () { if (isOpen) posDrop(); }, true);
    window.addEventListener('resize', function () { if (isOpen) posDrop(); });

    inp.__refreshItems = function (items) {
      allItems = items || []; loaded = true;
      if (isOpen) { showDrop(); filterLocalItems(); }
    };

    return inp;
  }

  /* ═══════════════════════════════════════════════════════════
     PERMISSION-AWARE BRANCH ACCESS
     1 branch  -> locked
     2+        -> All Branches + permitted branches
     Admin/System Manager -> true company-wide All Branches
  ═══════════════════════════════════════════════════════════ */

  var REF_ALL_BRANCH_ROLES = ['System Manager'];

  function userHasAllBranchAccess() {
    if (frappe.session && frappe.session.user === 'Administrator') {
      return true;
    }

    if (frappe.user && typeof frappe.user.has_role === 'function') {
      for (var i = 0; i < REF_ALL_BRANCH_ROLES.length; i += 1) {
        if (frappe.user.has_role(REF_ALL_BRANCH_ROLES[i])) {
          return true;
        }
      }
    }

    var roles =
      frappe.user_roles ||
      (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ||
      [];

    for (var j = 0; j < REF_ALL_BRANCH_ROLES.length; j += 1) {
      if (roles.indexOf(REF_ALL_BRANCH_ROLES[j]) !== -1) {
        return true;
      }
    }

    return false;
  }

  function loadPermittedBranches() {
    return new Promise(function (resolve, reject) {
      frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Branch',
          fields: ['name'],
          limit_page_length: 200,
          order_by: 'name asc'
        },
        callback: function (r) {
          var rows = (r && Array.isArray(r.message)) ? r.message : [];
          var names = rows.map(function (b) {
            return String((b && b.name) || '').trim();
          }).filter(Boolean);

          names = names.filter(function (name, index, arr) {
            return arr.indexOf(name) === index;
          });

          names.sort(function (a, b) {
            return a.localeCompare(b, undefined, { sensitivity: 'base' });
          });

          /*
            Employee Sale Master only uses operational branches.
            Head Office and Testing Branch are removed from the actual
            permission/fetch list, not merely hidden from the dropdown.
          */
          var excludedBranchNames = ['head office', 'testing branch'];

          names = names.filter(function (name) {
            return excludedBranchNames.indexOf(
              String(name || '').trim().toLowerCase()
            ) === -1;
          });

          HAS_ALL_BRANCH_ACCESS = userHasAllBranchAccess();
          BRANCH_ACCESS_RESTRICTED = !HAS_ALL_BRANCH_ACCESS;
          PERMITTED_BRANCHES = names.slice();

          if (BRANCH_ACCESS_RESTRICTED && !PERMITTED_BRANCHES.length) {
            reject(new Error('No permitted Branch was returned for this login.'));
            return;
          }

          if (BRANCH_ACCESS_RESTRICTED && PERMITTED_BRANCHES.length === 1) {
            USER_BRANCH = PERMITTED_BRANCHES[0];
          } else {
            USER_BRANCH = null;
          }

          void 0;

          resolve(PERMITTED_BRANCHES);
        },
        error: function (err) {
          reject(err || new Error('Unable to determine Branch access.'));
        }
      });
    });
  }

