  var bookingTypeInp = null;

  function initBranch() {
    var el = $('ref-f-branch');
    if (!el) return;

    /*
      Hide non-operational branches from the Branch selector only.
      Permission logic remains unchanged.
    */
    var HIDDEN_BRANCH_OPTIONS = ['head office', 'testing branch'];

    var names = PERMITTED_BRANCHES.filter(function (name) {
      var normalized = String(name || '').trim().toLowerCase();
      return HIDDEN_BRANCH_OPTIONS.indexOf(normalized) === -1;
    });

    /*
      Single permitted branch:
      show the branch and lock the selector.
    */
    if (BRANCH_ACCESS_RESTRICTED && names.length === 1) {
      makeDropdownSearch({
        targetEl: el,
        placeholder: names[0],
        disabled: true,
        supplier: function (cb) { cb([]); }
      });
      return;
    }

    /*
      Multiple permitted branches:
      show All Branches + only permitted branches.

      Administrator/System Manager:
      Branch get_list returns the company-wide list and All Branches
      means the true company-wide view.
    */
    var items = [{
      label: 'All Branches',
      value: '',
      displayValue: ''
    }].concat(
      names.map(function (name) {
        return {
          label: name,
          value: name,
          displayValue: name
        };
      })
    );

    var branchInp = makeDropdownSearch({
      targetEl: el,
      placeholder: 'All Branches',
      supplier: function (cb) {
        cb(items);
      }
    });

    if (branchInp && branchInp.__refreshItems) {
      branchInp.__refreshItems(items);
    }
  }

