  /* ═══════════════════════════════════════════════════════════
     EXCEL HELPERS
  ═══════════════════════════════════════════════════════════ */
  function xmlEscape(v) {
    v = (v === null || v === undefined) ? '' : String(v);
    return v.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
            .replace(/"/g,'&quot;').replace(/'/g,'&apos;');
  }

  function excelCell(value, isNumber) {
    var v = (value === null || value === undefined) ? '' : value;
    if (isNumber && v !== '' && isFinite(Number(v))) {
      return '<Cell><Data ss:Type="Number">' + Number(v) + '</Data></Cell>';
    }
    return '<Cell><Data ss:Type="String">' + xmlEscape(v) + '</Data></Cell>';
  }

  function buildExcelXml(sheetName, headers, rows, numberCols) {
    numberCols = numberCols || [];
    var xml = '';
    xml += '<?xml version="1.0"?>';
    xml += '<?mso-application progid="Excel.Sheet"?>';
    xml += '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"';
    xml += ' xmlns:o="urn:schemas-microsoft-com:office:office"';
    xml += ' xmlns:x="urn:schemas-microsoft-com:office:excel"';
    xml += ' xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">';
    xml += '<Styles>';
    xml += '<Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#0F3D1E"/><Interior ss:Color="#E8F5E9" ss:Pattern="Solid"/></Style>';
    xml += '</Styles>';
    xml += '<Worksheet ss:Name="' + xmlEscape(sheetName).slice(0, 31) + '">';
    xml += '<Table>';
    xml += '<Row>';
    headers.forEach(function (h) {
      xml += '<Cell ss:StyleID="Header"><Data ss:Type="String">' + xmlEscape(h) + '</Data></Cell>';
    });
    xml += '</Row>';
    rows.forEach(function (row) {
      xml += '<Row>';
      row.forEach(function (cell, idx) { xml += excelCell(cell, numberCols.indexOf(idx) >= 0); });
      xml += '</Row>';
    });
    xml += '</Table>';
    xml += '<WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel">';
    xml += '<FreezePanes/><FrozenNoSplit/><SplitHorizontal>1</SplitHorizontal><TopRowBottomPane>1</TopRowBottomPane>';
    xml += '</WorksheetOptions>';
    xml += '</Worksheet>';
    xml += '</Workbook>';
    return xml;
  }

  function downloadExcelXml(filename, sheetName, headers, rows, numberCols) {
    var xml = buildExcelXml(sheetName, headers, rows, numberCols);
    var blob = new Blob([xml], { type: 'application/vnd.ms-excel;charset=utf-8' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () {
      URL.revokeObjectURL(a.href);
      if (a.parentNode) a.parentNode.removeChild(a);
    }, 1000);
  }

  function exportGlobalExcel() {
    if (!RAW_DATA.length) {
      frappe.msgprint('Please Generate Report first before exporting.');
      return;
    }

    var filtered = applyFilters(RAW_DATA);
    if (!filtered.length) {
      frappe.msgprint('No records match current filters.');
      return;
    }

    var headers = [
      'Invoice','Invoice Date','Branch','Customer','Client Name','Booking Type',
      'Payment IDs','Payment Dates','Mode of Payment','Sharing Type',
      'Referring Employee','Referring Employee ID','Referring Share ex-GST',
      'Incentive Employee','Incentive Employee ID','Incentive Share ex-GST',
      'Paid ex-GST','GST','Paid w/ GST','Grand Total','Outstanding'
    ];

    var rows = filtered.map(function (r) {
      return [
        r.invoice || '',
        fmtDDMMYY(r.invoice_date),
        r.branch || '',
        r.customer || '',
        r.client_name || '',
        r.booking_type || '',
        r.payment_ids || '',
        r.payment_dates || '',
        r.mode_of_payment || '',
        r.sharing_type || '',
        r.referring_employee || '',
        r.referring_employee_id || r.referring_practitioner_id || '',
        round2(r.referring_employee_share),
        r.incentive_employee || '',
        r.incentive_employee_id || '',
        round2(r.incentive_employee_share),
        round2(r.paid_amount_without_gst),
        round2(r.gst_amount),
        round2(r.paid_amount),
        round2(r.grand_total),
        round2(r.outstanding_amount)
      ];
    });

    var f = fval('ref-f-from').split('-').reverse().join('-');
    var t2 = fval('ref-f-to').split('-').reverse().join('-');
    var br = getEffectiveBranch() || 'All';

    downloadExcelXml(
      'Referral_' + br + '_' + f + '_to_' + t2 + '.xls',
      'Transaction Detail',
      headers,
      rows,
      [12, 15, 16, 17, 18, 19, 20]
    );
  }

  /* ═══════════════════════════════════════════════════════════
     EMPLOYEE-WISE EXCEL EXPORT
  ═══════════════════════════════════════════════════════════ */
  function exportEmpExcel(rows) {
    if (!rows || !rows.length) {
      frappe.msgprint('No employee data to export.');
      return;
    }

    var headers = [
      'Rank','Employee','Branch','Emp ID','Invoices',
      'Paid ex-GST','GST','Paid w/ GST','Grand Total','Outstanding',
      'Top Booking Type','Mode of Payment'
    ];

    var dataRows = rows.map(function (e, i) {
      var topBt = Object.keys(e.bkCounts)
        .sort(function (a, b) { return e.bkCounts[b] - e.bkCounts[a]; })[0] || '';

      return [
        i + 1,
        e.name || '',
        e.branch || '',
        e.empId || '',
        e.cnt || 0,
        round2(e.exTax),
        round2(e.tax),
        round2(e.paid),
        round2(e.gt),
        round2(e.out),
        topBt,
        (e.modes || []).join('; ')
      ];
    });

    downloadExcelXml(
      'Referral_EmpWise_' + fval('ref-f-from') + '_to_' + fval('ref-f-to') + '.xls',
      'Employee Wise',
      headers,
      dataRows,
      [0, 4, 5, 6, 7, 8, 9]
    );
  }

  /* ═══════════════════════════════════════════════════════════
     FETCH
  ═══════════════════════════════════════════════════════════ */
  function runReferralReportForBranch(from, to, branch) {
    return new Promise(function (resolve, reject) {
      frappe.call({
        method: 'frappe.desk.query_report.run',
        args: {
          report_name: 'REFERRAL REPORT \u2013 FIXED',
          filters: {
            from_date: from,
            to_date: to,
            branch: branch || ''
          },
          ignore_prepared_report: 1
        },
        callback: function (r) {
          if (r && r.exc) {
            reject(new Error(String(r.exc)));
            return;
          }

          var raw = (r && r.message && Array.isArray(r.message.result))
            ? r.message.result
            : [];

          void 0;

          var normalized = raw
            .filter(function (row) {
              return row && typeof row === 'object' && !Array.isArray(row);
            })
            .map(normalizeReportRow)
            .filter(function (row) {
              return !!row.invoice;
            });

          void 0;

          /*
            This Web Page is invoice-driven.
            If the report returns rows but no row has an Invoice field,
            the report SQL was changed to an employee-summary structure.
            Do not silently show "No data"; surface the real cause.
          */
          if (raw.length && !normalized.length) {
            reject(new Error(
              'REFERRAL REPORT \u2013 FIXED returned data, but no Invoice field was found. ' +
              'This Web Page requires the invoice-wise report output.'
            ));
            return;
          }

          /*
            Defense in depth:
            when a named Branch was requested, retain only that Branch even
            if the report implementation unexpectedly returns extra rows.
          */
          if (branch) {
            normalized = normalized.filter(function (row) {
              return String(row.branch || '') === String(branch);
            });
          }

          resolve(normalized);
        },
        error: function (err) {
          reject(err || new Error('Referral report request failed.'));
        }
      });
    });
  }

  function fetchData(callback) {
    var from = fval('ref-f-from');
    var to = fval('ref-f-to');
    var selectedBranch = getEffectiveBranch();

    if (!from || !to) {
      setStatus('Please select From and To dates.', true);
      return;
    }

    if (
      BRANCH_ACCESS_RESTRICTED &&
      selectedBranch &&
      PERMITTED_BRANCHES.indexOf(selectedBranch) === -1
    ) {
      setStatus('You do not have access to the selected Branch.', true);
      return;
    }

    var branchesToFetch;

    /*
      Restricted multi-branch + All Branches:
      NEVER call the report with branch=''.
      Fetch each permitted branch separately and combine the rows.
    */
    if (
      BRANCH_ACCESS_RESTRICTED &&
      !selectedBranch &&
      PERMITTED_BRANCHES.length > 1
    ) {
      branchesToFetch = PERMITTED_BRANCHES.slice();
    } else {
      branchesToFetch = [selectedBranch || ''];
    }

    var statusBranch =
      selectedBranch ||
      (
        BRANCH_ACCESS_RESTRICTED
          ? 'All Permitted Branches'
          : 'All Branches'
      );

    setStatus('\u23f3 Fetching data for ' + statusBranch + '...');

    Promise.all(
      branchesToFetch.map(function (branch) {
        return runReferralReportForBranch(from, to, branch);
      })
    ).then(function (groups) {
      RAW_DATA = [];

      groups.forEach(function (rows) {
        (rows || []).forEach(function (row) {
          RAW_DATA.push(row);
        });
      });

      void 0;

      /*
        A restricted login can never retain a row outside its permitted
        Branch list, including in an All Branches view.
      */
      if (BRANCH_ACCESS_RESTRICTED && PERMITTED_BRANCHES.length) {
        RAW_DATA = RAW_DATA.filter(function (row) {
          return PERMITTED_BRANCHES.indexOf(String(row.branch || '')) !== -1;
        });
      }

      void 0;

      if (bookingTypeInp && bookingTypeInp.__refreshItems) {
        var seen = {};

        RAW_DATA.forEach(function (row) {
          if (row.booking_type) seen[row.booking_type] = true;
        });

        var btItems = [{ label: 'All Booking Types', value: '' }].concat(
          Object.keys(seen).sort().map(function (bt) {
            return { label: bt, value: bt };
          })
        );

        bookingTypeInp.__refreshItems(btItems);
      }

      setStatus('');
      callback(RAW_DATA);
    }).catch(function (err) {
      void 0;

      var message =
        (err && err.message)
          ? err.message
          : 'Unable to load the report for the permitted Branch access.';

      setStatus(message, true);
    });
  }

  /* ═══════════════════════════════════════════════════════════
     FILTERS
  ═══════════════════════════════════════════════════════════ */
  function applyFilters(data) {
    var branch = getEffectiveBranch().toLowerCase();
    var booking = fval('ref-f-booking').toLowerCase();
    var mopF = fval('ref-f-mop').toLowerCase();
    var employeeState = getEmployeeFilterState();

    if (branch === 'all branches') branch = '';
    if (booking === 'all booking types') booking = '';
    if (mopF === 'all modes of payment') mopF = '';

    var paidMin = getAmountVal('ref-f-paid-from');
    var paidMax = getAmountVal('ref-f-paid-to');
    var outMin = getAmountVal('ref-f-out-from');
    var outMax = getAmountVal('ref-f-out-to');

    return (data || []).filter(function (r) {
      if (
        BRANCH_ACCESS_RESTRICTED &&
        PERMITTED_BRANCHES.length &&
        PERMITTED_BRANCHES.indexOf(String(r.branch || '')) === -1
      ) return false;

      if (branch && String(r.branch || '').toLowerCase() !== branch) return false;
      if (booking && String(r.booking_type || '').toLowerCase() !== booking) return false;
      if (!invoiceMatchesEmployee(r, employeeState)) return false;

      if (mopF) {
        var tokens = String(r.mode_of_payment || '').split(',').map(function (t) {
          return t.trim().toLowerCase();
        });
        if (!tokens.some(function (t) { return t.indexOf(mopF) >= 0; })) return false;
      }

      var exGst = num(r.paid_amount_without_gst);
      var outstanding = num(r.outstanding_amount);

      if (paidMin !== null && exGst < paidMin) return false;
      if (paidMax !== null && exGst > paidMax) return false;
      if (outMin !== null && outstanding < outMin) return false;
      if (outMax !== null && outstanding > outMax) return false;

      return true;
    });
  }

  /* ═══════════════════════════════════════════════════════════
     RENDER: OVERVIEW
  ═══════════════════════════════════════════════════════════ */
  function renderOverview(invoiceData, employeeCredits) {
    invoiceData = invoiceData || [];
    employeeCredits = employeeCredits || [];

    var invoiceSeen = {};
    var paid = 0;
    var tax = 0;
    var exTax = 0;
    var gt = 0;
    var out = 0;

    /* Employee-credit rows are allocated shares. Their sum equals the
       invoice total when no employee filter is used, and equals only the
       selected employee's sale value when an employee filter is active. */
    employeeCredits.forEach(function (r) {
      if (r.invoice) invoiceSeen[r.invoice] = true;
      paid += num(r.paid_amount);
      tax += num(r.tax_amount);
      exTax += num(r.paid_amount_without_tax);
      gt += num(r.grand_total);
      out += num(r.outstanding_amount);
    });

    var inv = Object.keys(invoiceSeen).length;
    if (!employeeCredits.length) inv = invoiceData.length;

    $('ref-ov-tiles').innerHTML = [
      { l: 'Total Invoices', v: inv.toLocaleString(), bg: 't-pn' },
      { l: 'Employee Sale (ex-GST)', v: fmtCardAmount(exTax), bg: 't-pgr', amount: true },
      { l: 'Allocated GST', v: fmtCardAmount(tax), bg: 't-pg', amount: true },
      { l: 'Employee Sale (w/ GST)', v: fmtCardAmount(paid), bg: 't-pn', amount: true },
      { l: 'Allocated Grand Total', v: fmtCardAmount(gt), bg: 't-pg', amount: true },
      { l: 'Allocated Outstanding', v: fmtCardAmount(out), bg: 't-pr', amount: true }
    ].map(function (t) {
      return '<div class="ref-tile ' + t.bg + '"><div class="tl">' + t.l +
        '</div><div class="tv' + (t.amount ? ' ref-amount-with-compact' : '') + '">' +
        t.v + '</div></div>';
    }).join('');

    var eMap = {};
    employeeCredits.forEach(function (r) {
      var key = employeeGroupKey(r);
      var displayName = cleanEmployeeDisplayName(r.sales_person_name) || '(No Employee)';

      if (!eMap[key]) {
        eMap[key] = { name: displayName, exTax: 0 };
      }

      eMap[key].exTax += num(r.paid_amount_without_tax);
    });

    var topE = Object.values(eMap)
      .sort(function (a, b) { return b.exTax - a.exTax; })
      .slice(0, 10);
    var maxE = topE.length ? topE[0].exTax : 1;

    $('ref-ov-emp-bars').innerHTML = topE.map(function (e) {
      return '<div class="ref-bar-row"><div class="ref-bar-lbl" title="' + esc(e.name) + '">' +
        esc(e.name) + '</div><div class="ref-bar-track"><div class="ref-bar-fill" style="width:' +
        Math.round(e.exTax / maxE * 100) +
        '%;background:linear-gradient(90deg,#43A047,#1B5E20)"></div></div>' +
        '<div class="ref-bar-val">' + fmt(e.exTax) + '</div></div>';
    }).join('') || '<div class="ref-loading">No data</div>';

    var bMap = {};
    employeeCredits.forEach(function (r) {
      var key = r.branch || 'Unknown';
      if (!bMap[key]) bMap[key] = { name: key, exTax: 0 };
      bMap[key].exTax += num(r.paid_amount_without_tax);
    });

    var topB = Object.values(bMap).sort(function (a, b) { return b.exTax - a.exTax; });
    var maxB = topB.length ? topB[0].exTax : 1;

    $('ref-ov-branch-bars').innerHTML = topB.map(function (b) {
      return '<div class="ref-bar-row"><div class="ref-bar-lbl">' + esc(b.name) + '</div>' +
        '<div class="ref-bar-track"><div class="ref-bar-fill" style="width:' +
        Math.round(b.exTax / maxB * 100) +
        '%;background:linear-gradient(90deg,#81C784,#2E7D32)"></div></div>' +
        '<div class="ref-bar-val">' + fmt(b.exTax) + '</div></div>';
    }).join('') || '<div class="ref-loading">No data</div>';

    var btMap = {};
    employeeCredits.forEach(function (r) {
      var key = r.booking_type || 'Unknown';
      if (!btMap[key]) {
        btMap[key] = {
          bt: key,
          invoiceSeen: {},
          cnt: 0,
          paid: 0,
          tax: 0,
          exTax: 0,
          out: 0
        };
      }

      var b = btMap[key];
      if (r.invoice && !b.invoiceSeen[r.invoice]) {
        b.invoiceSeen[r.invoice] = true;
        b.cnt += 1;
      }
      b.paid += num(r.paid_amount);
      b.tax += num(r.tax_amount);
      b.exTax += num(r.paid_amount_without_tax);
      b.out += num(r.outstanding_amount);
    });

    $('ref-ov-booking-body').innerHTML = Object.values(btMap)
      .sort(function (a, b) { return b.exTax - a.exTax; })
      .map(function (b) {
        return '<tr>' +
          '<td><span class="rpill rp-go">' + esc(b.bt) + '</span></td>' +
          '<td class="rnum">' + b.cnt + '</td>' +
          '<td class="rnum" style="color:#1B5E20;font-weight:800">' + fmt(b.exTax) + '</td>' +
          '<td class="rnum">' + fmt(b.tax) + '</td>' +
          '<td class="rnum" style="color:#5F6F63">' + fmt(b.paid) + '</td>' +
          '<td class="rnum" style="color:' + (b.out > 0 ? '#C62828' : '#5F6F63') + '">' +
          fmt(b.out) + '</td></tr>';
      }).join('') || '<tr><td colspan="6" class="ref-loading">No data</td></tr>';
  }

  /* ═══════════════════════════════════════════════════════════
     RENDER: EMPLOYEE WISE
     Displays one combined Paid (ex-GST) amount per employee
  ═══════════════════════════════════════════════════════════ */
  function renderEmployeeWise(data) {
    var empMap = {};

    (data || []).forEach(function (r) {
      var key = employeeGroupKey(r);
      var displayName = cleanEmployeeDisplayName(r.sales_person_name) || '(No Employee)';

      if (!empMap[key]) {
        var groupedEmpId =
          r.employee_id ||
          EMPLOYEE_NAME_ID_MAP[normalizedEmployeeName(r.sales_person_name)] ||
          r.sales_person_id ||
          '';

        empMap[key] = {
          name: displayName,
          empId: groupedEmpId,
          branches: [],
          invoiceSeen: {},
          cnt: 0,
          paid: 0,
          tax: 0,
          exTax: 0,
          gt: 0,
          out: 0,
          refEx: 0,
          incEx: 0,
          bkCounts: {},
          modes: []
        };
      }

      var e = empMap[key];

      /* Prefer a real Employee ID over a Practitioner ID whenever available. */
      if (r.employee_id) {
        e.empId = r.employee_id;
      } else if (!e.empId && r.sales_person_id) {
        e.empId = r.sales_person_id;
      }

      if (r.branch && e.branches.indexOf(r.branch) < 0) e.branches.push(r.branch);

      if (!e.invoiceSeen[r.invoice]) {
        e.invoiceSeen[r.invoice] = true;
        e.cnt += 1;
      }

      e.paid += num(r.paid_amount);
      e.tax += num(r.tax_amount);
      e.exTax += num(r.paid_amount_without_tax);
      e.gt += num(r.grand_total);
      e.out += num(r.outstanding_amount);

      if (String(r.credit_type || '').toLowerCase() === 'incentive') {
        e.incEx += num(r.paid_amount_without_tax);
      } else {
        e.refEx += num(r.paid_amount_without_tax);
      }

      var bt = r.booking_type || 'Unknown';
      e.bkCounts[bt] = (e.bkCounts[bt] || 0) + 1;

      if (r.mode_of_payment) {
        String(r.mode_of_payment).split(',').forEach(function (mo) {
          var mt = mo.trim();
          if (mt && e.modes.indexOf(mt) < 0) e.modes.push(mt);
        });
      }
    });

    var rows = Object.values(empMap)
      .map(function (e) {
        e.branch = e.branches.join(', ');
        return e;
      })
      .sort(function (a, b) { return b.exTax - a.exTax; });

    var old = R.querySelector('#ref-emp-ctrl-row');
    if (old) old.parentNode.removeChild(old);

    var ctrl = document.createElement('div');
    ctrl.id = 'ref-emp-ctrl-row';
    ctrl.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px;';
    ctrl.innerHTML =
      '<input id="ref-emp-srch" type="text" placeholder="\uD83D\uDD0D Search employee name..."' +
      ' style="flex:1;min-width:160px;height:34px;padding:0 12px;font-size:12px;' +
      'border:1.5px solid #A5D6A7;border-radius:9px;outline:none;' +
      'background:#FFFFFF;color:#152418;box-shadow:0 1px 2px rgba(15,61,30,.05);"/>' +
      '<input id="ref-emp-mop-srch" type="text" placeholder="\uD83D\uDD0D Search mode of payment..."' +
      ' style="flex:1;min-width:160px;height:34px;padding:0 12px;font-size:12px;' +
      'border:1.5px solid #A5D6A7;border-radius:9px;outline:none;' +
      'background:#FFFFFF;color:#152418;box-shadow:0 1px 2px rgba(15,61,30,.05);"/>' +
      '<button id="ref-emp-xlsx" style="height:34px;padding:0 16px;font-size:12px;font-weight:600;' +
      'background:linear-gradient(135deg,#2E7D32,#1B5E20);color:#fff;' +
      'border:1.5px solid #1B5E20;border-radius:9px;cursor:pointer;' +
      'box-shadow:0 3px 10px rgba(27,94,32,.22);white-space:nowrap;">' +
      '\u2B07 Export Employee Excel</button>';

    var tbl = R.querySelector('#ref-emp-body') && R.querySelector('#ref-emp-body').closest('table');
    if (tbl) tbl.parentNode.insertBefore(ctrl, tbl);

    $('ref-emp-body').innerHTML = rows.map(function (e, i) {
      var topBt = Object.keys(e.bkCounts)
        .sort(function (a, b) { return e.bkCounts[b] - e.bkCounts[a]; })[0] || '';
      var oc = e.out > 10000 ? '#C62828' : e.out > 0 ? '#E65100' : '#5F6F63';

      return '<tr>' +
        '<td>' + rankBadge(i) + '</td>' +
        '<td><strong>' + esc(e.name) + '</strong></td>' +
        '<td><span class="rpill rp-n">' + esc(e.branch) + '</span></td>' +
        '<td style="font-size:9px;color:#6B7C70">' + esc(e.empId) + '</td>' +
        '<td class="rnum">' + e.cnt + '</td>' +
        '<td class="rnum" style="color:#1B5E20;font-weight:800">' + fmt(e.exTax) + '</td>' +
        '<td class="rnum" style="color:#5F6F63">' + fmt(e.tax) + '</td>' +
        '<td class="rnum" style="color:#5F6F63">' + fmt(e.paid) + '</td>' +
        '<td class="rnum">' + fmt(e.gt) + '</td>' +
        '<td class="rnum" style="color:' + oc + '">' + fmt(e.out) + '</td>' +
        '<td><span class="rpill rp-go">' + esc(topBt) + '</span></td>' +
        '<td style="font-size:9px;max-width:140px;overflow:hidden;text-overflow:ellipsis">' +
        esc(e.modes.join(', ')) + '</td></tr>';
    }).join('') || '<tr><td colspan="12" class="ref-loading">No data</td></tr>';

    function empFilter() {
      var et = (R.querySelector('#ref-emp-srch') ? R.querySelector('#ref-emp-srch').value : '').toLowerCase();
      var mt = (R.querySelector('#ref-emp-mop-srch') ? R.querySelector('#ref-emp-mop-srch').value : '').toLowerCase();

      R.querySelectorAll('#ref-emp-body tr').forEach(function (tr) {
        var c = tr.querySelectorAll('td');
        var en = c[1] ? c[1].textContent.toLowerCase() : '';
        var mp = c[11] ? c[11].textContent.toLowerCase() : '';
        tr.style.display = (!et || en.indexOf(et) >= 0) && (!mt || mp.indexOf(mt) >= 0) ? '' : 'none';
      });
    }

    var es = R.querySelector('#ref-emp-srch');
    var ms = R.querySelector('#ref-emp-mop-srch');
    if (es) { es.oninput = empFilter; es.value = ''; }
    if (ms) { ms.oninput = empFilter; ms.value = ''; }

    var xb = R.querySelector('#ref-emp-xlsx');
    if (xb) xb.onclick = function () { exportEmpExcel(rows); };
  }

