        '<td class="rnum" style="color:#1B5E20;font-weight:800">' + fmt(r.paid_amount_without_gst) + '</td>' +
        '<td class="rnum" style="color:#5F6F63">' + fmt(r.gst_amount) + '</td>' +
        '<td class="rnum" style="color:#5F6F63">' + fmt(r.paid_amount) + '</td>' +
        '<td class="rnum">' + fmt(r.grand_total) + '</td>' +
        '<td class="rnum" style="color:' + oc + '">' + fmt(r.outstanding_amount) + '</td>' +
        '</tr>';
    }).join('') || '<tr><td colspan="17" class="ref-loading">No data</td></tr>';
  }

  /* ═══════════════════════════════════════════════════════════
     MAIN
  ═══════════════════════════════════════════════════════════ */
  function fetchAndRender() {
    if (!validateAmountFilters(true)) return;

    fetchData(function (raw) {
      var filteredInvoices = applyFilters(raw);

      var allEmployeeCredits = buildEmployeeCreditRows(filteredInvoices);

      /*
        Build aliases before any employee aggregation.
        This fixes duplicate visible employees such as B Madhavi where one
        credit row has HR-EMP-00223 and another row has the same name but no ID.
      */
      rebuildEmployeeNameIdMap(allEmployeeCredits);

      var employeeCredits = filterEmployeeCredits(allEmployeeCredits);

      setStatus(
        filteredInvoices.length + ' invoices and ' +
        employeeCredits.length + ' employee credits loaded for ' +
        (
          getEffectiveBranch() ||
          (BRANCH_ACCESS_RESTRICTED ? 'All Permitted Branches' : 'All Branches')
        ) +
        ' \u2014 ' + new Date().toLocaleTimeString('en-IN')
      );

      renderOverview(filteredInvoices, employeeCredits);
      renderEmployeeWise(employeeCredits);
      renderBranchWise(filteredInvoices, employeeCredits);
      renderTransactions(filteredInvoices);
    });
  }

  /* ═══════════════════════════════════════════════════════════
     BOOT
  ═══════════════════════════════════════════════════════════ */
  /*
    WEB PAGE BOOT FIX:
    The previous version queried User Permission with limit:1 and locked
    the dashboard to the first Branch returned. The Web Page now starts
    with the same all-branch selector behaviour as the Custom HTML Block.
  */
  USER_BRANCH = null;

  var LIFE_CURRENT_USER =
    (frappe.session && frappe.session.user) ||
    (frappe.boot && frappe.boot.user && frappe.boot.user.name) ||
    '';

  void 0;

  loadPermittedBranches()
    .then(function () {
      initBranch();
      initBookingType();
      initEmployee();
      initMoP();
      setupAmountFilterValidation();
      buildGlobalExcelBtn();
      fetchAndRender();
    })
    .catch(function (err) {
      void 0;

      setStatus(
        'Branch access could not be verified for this login. Report loading has been blocked.',
        true
      );
    });


  }

  if (document.readyState === 'loading') {
    document.addEventListener(
      'DOMContentLoaded',
      initReferralReportWebPage,
      { once: true }
    );
  } else {
    initReferralReportWebPage();
  }
})();
